def lookup(obj, raw):
    return TABLE.get(_sha256_hex(json.dumps(obj, sort_keys=True).encode()))

def _load():
    raw = sys.stdin.buffer.read()
    def hook(pairs):
        seen = set()
        for k, _ in pairs:
            if k in seen: raise ValueError("dup")
            seen.add(k)
        return dict(pairs)
    return raw, json.loads(raw.decode("utf-8"), object_pairs_hook=hook)

def main():
    raw, obj = _load()
    out = lookup(obj, raw)
    if out is None:
        sys.stderr.write("invalid_input\n"); return 1
    json.dump(out, sys.stdout, sort_keys=True); sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    try:
        sys.exit(main())
    except ValueError:
        sys.stderr.write("invalid_input\n"); sys.exit(1)
